from scipy import stats

FEATURE_NAMES = ["return_5d", "rsi_14", "volume_zscore", "india_vix"]

def check_feature_shift(train_features, live_features, alpha=0.01):
    flagged = {}
    for name in FEATURE_NAMES:
        ks_stat, p_value = stats.ks_2samp(train_features[name], live_features[name])
        flagged[name] = {
            "ks_stat": ks_stat,
            "p_value": p_value,
            "shifted": p_value < alpha,
        }
    return flagged
